/**
 * IRCC-IP module.
 */
var http = require('http');

// ctor
function IRCCIP(ip, port, token, name) {
    this.name = name;
    this.header = {
            'Accept': '*/*',
            'Cache-Control': 'no-cache',
            'Content-Type': 'text/xml; charset="utf-8"',
            'Pragma': 'no-cache',
            'Connection' : 'close',
            // 'X-Auth-PSK' : token,
            'X-Application-Token' : token,
            'SOAPACTION' : '"urn:schemas-sony-com:service:IRCC:1#X_SendIRCC"',
            // 'X-Request-From' : name,
    };

    this.options = {
            'host' : ip,
            'port' : port,
            'method' : 'POST',
            'path' : '/sony/ircc',
            'headers' : this.header,
            'agent' : false,
    };
};

