IRCCIP.IRCC_ENVELOPE_PREFIX = '<s:Envelope\n \
      xmlns:s=\"http://schemas.xmlsoap.org/soap/envelope/\"\n \
      s:encodingStyle=\"http://schemas.xmlsoap.org/soap/encoding/\">\n \
      <s:Body>\n \
          <u:X_SendIRCC xmlns:u=\"urn:schemas-sony-com:service:IRCC:1\">\n \
          <IRCCCode>';

IRCCIP.IRCC_ENVELOPE_POSTFIX = '</IRCCCode>\n \
          </u:X_SendIRCC>\n \
     </s:Body>\n \
  </s:Envelope>';

IRCCIP.prototype.send = function(cmd, callback, internal) {
    if (isNaN(cmd) || !isFinite(cmd) || cmd >= IRCCIP.IRCC_CODE.length || cmd < 0) {
        callback('<errorCode>error');
        return;
    }

    if (IRCCIP.IRCC_CODE[cmd] == "") {
        logger.dlog(Logger.VERBOSE, '[IRCC][EVENT] IRCC cmd=' + cmd + ' is not supported');
        callback('<errorCode>error');
        return;
    }

    var envelope = IRCCIP.IRCC_ENVELOPE_PREFIX + IRCCIP.IRCC_CODE[cmd]
            + IRCCIP.IRCC_ENVELOPE_POSTFIX;

    if (!internal) { // undefined or null or false
        this.header['X-Request-From'] = this.name;
    } else {
        delete this.header['X-Request-From'];
    }

    //logger.dlog(Logger.VERBOSE, '[IRCC] Caller         => ' + IRCCIP.prototype.send.caller);
    logger.dlog(Logger.VERBOSE, '[IRCC] X-Request-From => ' + this.header['X-Request-From']);

    this.header['Content-Length'] = envelope.length;

    // req is an instance of the http.ClientRequest class.
    var req = http.request(this.options, function(res) {
        var body = '';
        res.setEncoding('utf8');
        res.on('data', function(chunk) {
            body += chunk;
        });
        res.on('end', function() {
            // response value
            logger.dlog(Logger.VERBOSE, '[IRCC][EVENT] http end');
            logger.dlog(Logger.VERBOSE, '[IRCC][EVENT] http DATA => ' + body);
            if (body.match(/Action not authorized/)) {
                logger.rlog(Logger.WARN, '[IRCC] >>>>> Pre-Shared Key is not set <<<<<');
            }
            callback(body);
        });
    });

    req.on('error', function(e) {
        // error
        logger.rlog(Logger.ERROR, '[IRCC][EVENT] ClientRequest error (' + e.message + ')');
        callback('<errorCode>error');
    });

    req.setTimeout(IRCCIP.TIMEOUT, function() {
        logger.rlog(Logger.INFO, '[IRCC][EVENT] ClientRequest timeout');
        callback('<errorCode>timeout');
    });
    req.write(envelope);
    req.end();
};

exports.IRCCIP = IRCCIP;

exports.createIRCCIP = function(ip, port, token, name) {
    return new IRCCIP(ip, port, token, name);
};
